function reportFrom(source,type,filters,product=''){archiveReportActive=null;lastReportSource=source;$('#reportType').value=type;$('#reportType').dataset.product=product;$('#reportType').dataset.macro=source==='archive'?purchaseGenre:'';setFilters('reportFilters',filters);$('#periodPreset').value='custom';showPage('reports')}
function applyPeriod(){let p=$('#periodPreset').value,now=today(),f=getFilters('reportFilters');if(p==='week'){let d=new Date(now+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));f.from=d.toLocaleDateString('sv-SE');d.setDate(d.getDate()+6);f.to=d.toLocaleDateString('sv-SE')}if(p==='quarter'){let d=new Date(now+'T12:00:00'),m=Math.floor(d.getMonth()/3)*3;f.from=new Date(d.getFullYear(),m,1).toLocaleDateString('sv-SE');f.to=new Date(d.getFullYear(),m+3,0).toLocaleDateString('sv-SE')}if(p==='month'){f.from=now.slice(0,7)+'-01';f.to=now.slice(0,7)+'-31';let d=new Date(Number(now.slice(0,4)),Number(now.slice(5,7)),0);f.to=d.toLocaleDateString('sv-SE')}if(p==='year'){f.from=now.slice(0,4)+'-01-01';f.to=now.slice(0,4)+'-12-31'}if(p==='all'){f.from='';f.to=''}setFilters('reportFilters',f);renderReport()}
