async function reportPDFBlob(report){await loadScript('vendor/pdf-lib.min.js','PDFLib');const {PDFDocument,StandardFonts,rgb}=PDFLib,pdf=await PDFDocument.create(),font=await pdf.embedFont(StandardFonts.Helvetica),bold=await pdf.embedFont(StandardFonts.HelveticaBold);let page,y,pageN=0;function newPage(){page=pdf.addPage([595.28,841.89]);y=790;pageN++;page.drawText('TeFinanza | TeFinanza',{x:40,y:810,size:10,font:bold,color:rgb(.1,.3,.24)});page.drawText('Pagina '+pageN,{x:480,y:25,size:9,font})}newPage();for(let text of report.pdfLines){text=String(text).replace(/€/g,' EUR').replace(/[\u2013\u2014]/g,'-').replace(/[^\x20-\x7e\u00a0-\u00ff]/g,' ');let words=text.split(' '),line='';for(const word of words){let next=line?line+' '+word:word;if(font.widthOfTextAtSize(next,10)>510&&line){if(y<50)newPage();page.drawText(line,{x:40,y,size:10,font});y-=15;line=word}else line=next;while(font.widthOfTextAtSize(line,10)>510){let n=line.length;while(n>1&&font.widthOfTextAtSize(line.slice(0,n),10)>510)n--;if(y<50)newPage();page.drawText(line.slice(0,n),{x:40,y,size:10,font});y-=15;line=line.slice(n)}}if(y<50)newPage();page.drawText(line,{x:40,y,size:10,font});y-=22}return new Blob([await pdf.save()],{type:'application/pdf'})}
