function csvRows(rows){if(!rows.length)return '';let keys=Object.keys(rows[0]);const quote=s=>'"'+String(s??'').replaceAll('"','""')+'"';return '\ufeff'+keys.map(quote).join(';')+'\r\n'+rows.map(r=>keys.map(k=>quote(r[k])).join(';')).join('\r\n')}
