async function viewDocument(id){let d=state.documents.find(d=>d.id===id);if(!d)return toast('Documento non trovato.');let f=await dbGet('files',id);if(originalURL)URL.revokeObjectURL(originalURL);$('#viewContent').innerHTML=`<h2>${esc(d.name)}</h2><button class="btn" data-rename-doc="${esc(d.id)}">RINOMINA FILE</button><p class="small">${esc(d.kind)} · ${esc(d.merchant||d.bank||'')} · ${esc(dateLabel(d.date))}</p><div id="originalPreview"></div><h3>Testo conservato</h3><pre style="white-space:pre-wrap;font-size:12px">${esc(d.text)}</pre>`;if(f){originalURL=URL.createObjectURL(f.blob);if(f.blob.type.startsWith('image/'))$('#originalPreview').innerHTML=`<img class="doc-preview" src="${originalURL}" alt="Documento originale">`;else if(f.blob.type==='application/pdf')$('#originalPreview').innerHTML=`<iframe class="preview-frame" title="Documento originale" src="${originalURL}"></iframe>`}$('#downloadOriginal').disabled=!f;$('#downloadOriginal').onclick=()=>f&&saveBlob(f.blob,d.name);$('#viewModal').showModal()}
async function ocrWorker(){if(worker)return worker;await loadScript('vendor/tesseract.min.js','Tesseract');worker=await Tesseract.createWorker('ita+eng',1,{workerPath:new URL('vendor/worker.min.js',location.href).href,corePath:new URL('vendor/tesseract-core-lstm.wasm.js',location.href).href,langPath:new URL('vendor/',location.href).href.replace(/\/$/,''),logger:m=>{if($('#ocrStatus'))$('#ocrStatus').textContent='OCR: '+m.status+' '+(m.progress?Math.round(m.progress*100)+'%':'')}});return worker}
async function cleanCanvas(source,rotation=0,enhance=true){let width=source.width||source.naturalWidth,height=source.height||source.naturalHeight;if(!width||!height)throw Error('Immagine non leggibile');let scale=Math.min(2.5,2200/Math.min(width,height),Math.sqrt(8000000/(width*height)),14000/Math.max(width,height));let c=document.createElement('canvas'),w=Math.max(1,Math.round(width*scale)),h=Math.max(1,Math.round(height*scale));c.width=rotation%180?h:w;c.height=rotation%180?w:h;let ctx=c.getContext('2d',{willReadFrequently:true});ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.translate(c.width/2,c.height/2);ctx.rotate(rotation*Math.PI/180);ctx.drawImage(source,-w/2,-h/2,w,h);if(enhance){let image=ctx.getImageData(0,0,c.width,c.height),d=image.data,hist=new Uint32Array(256);for(let i=0;i<d.length;i+=4){let g=Math.round(d[i]*.299+d[i+1]*.587+d[i+2]*.114);hist[g]++}let n=d.length/4,lo=0,hi=255,acc=0;for(let v=0;v<256;v++){acc+=hist[v];if(acc>n*.015){lo=v;break}}acc=0;for(let v=255;v>=0;v--){acc+=hist[v];if(acc>n*.02){hi=v;break}}let range=Math.max(hi-lo,50);for(let i=0;i<d.length;i+=4){let g=(d[i]*.299+d[i+1]*.587+d[i+2]*.114-lo)*255/range;d[i]=d[i+1]=d[i+2]=Math.max(0,Math.min(255,g))}ctx.putImageData(image,0,0)}return c}
async function recognizeCanvas(canvas,mode='3'){let w=await ocrWorker();await w.setParameters({tessedit_pageseg_mode:mode,preserve_interword_spaces:'1',user_defined_dpi:'300'});let r=await w.recognize(canvas,{}, {text:true,tsv:true});let layout=C.ocrLayout(r.data.tsv);return{text:layout||r.data.text||'',confidence:r.data.confidence||0}}
