document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-safari-guide')){showPage('help');requestAnimationFrame(()=>$('#safariGuide').scrollIntoView({behavior:'smooth',block:'start'}))}if(b.dataset.goto)showPage(b.dataset.goto);if(b.dataset.page)showPage(b.dataset.page);if(b.dataset.accountEdit)editAccount(b.dataset.accountEdit);if(b.dataset.accountOps){let a=state.accounts.find(a=>a.id===b.dataset.accountOps);setFilters('movementFilters',{account:a.name});showPage('movements')}if(b.dataset.accountReport){let a=state.accounts.find(a=>a.id===b.dataset.accountReport);reportFrom('accounts','movements',{account:a.name})}if(b.dataset.accountReset)resetDialog(b.dataset.accountReset);if(b.dataset.accountDelete){let a=state.accounts.find(a=>a.id===b.dataset.accountDelete);if(C.ledgerRows(state,{account:a.name},accountLinks()).length||state.positions.some(p=>p.account===a.name)||state.utilities.some(u=>u.accountId===a.id)||state.bills.some(x=>x.accountId===a.id))return toast('Il conto contiene operazioni, posizioni o utenze: spostale o eliminale prima di eliminare il conto.');if(confirm('Eliminare il conto '+a.name+'?'))await change(s=>s.accounts=s.accounts.filter(a=>a.id!==b.dataset.accountDelete))}if(b.dataset.edit)editMovement(b.dataset.edit);if(b.dataset.viewDoc)await viewDocument(b.dataset.viewDoc);if(b.dataset.position)editPosition(b.dataset.position);if(b.dataset.positionDelete&&confirm('Eliminare questa posizione?'))await change(s=>s.positions=s.positions.filter(p=>p.id!==b.dataset.positionDelete));if(b.dataset.documentDelete&&confirm('Eliminare il documento e il suo originale? Le operazioni collegate rimangono.')){let id=b.dataset.documentDelete;if(await change(s=>{s.documents=s.documents.filter(d=>d.id!==id);s.movements.forEach(m=>{if(m.docId===id)delete m.docId});s.bills.forEach(b=>{if(b.docId===id)delete b.docId})})){let tx=db.transaction('files','readwrite');tx.objectStore('files').delete(id)}}}catch(error){toast(error.message)}});
$('#newMovement').onclick=()=>editMovement();$('#addAccount').onclick=()=>editAccount();$('#addPosition').onclick=()=>editPosition();$('#transferBtn').onclick=transfer;$('#newDocument').onclick=startDocument;$('#docFile').onchange=e=>{if(e.target.files[0])runOCR(e.target.files[0]);e.target.value=''};$('#closeDoc').onclick=()=>$('#docModal').close();$('#docModal').addEventListener('cancel',e=>{if($('#closeDoc').disabled)e.preventDefault()});$('#closeView').onclick=()=>{$('#viewModal').close();if(originalURL)URL.revokeObjectURL(originalURL)};$('#productSearch').oninput=()=>markPurchaseDraft();$('#movReport').onclick=()=>reportFrom('movements','movements',getFilters('movementFilters'));$('#archiveReport').onclick=()=>openPurchaseReport();$('#portfolioReport').onclick=()=>reportFrom('portfolio','portfolio',getFilters('portfolioFilters'));$('#reportType').onchange=()=>{archiveReportActive=null;spendingReportCache=null;delete $('#reportType').dataset.product;delete $('#reportType').dataset.macro;renderReport()};$('#groupBy').onchange=renderReport;$('#horizon').onchange=renderReport;$('#periodPreset').onchange=applyPeriod;$('#backReport').onclick=()=>showPage(lastReportSource);$('#pdfBtn').onclick=makePDF;$('#printReport').onclick=()=>window.print();$('#reportCSV').onclick=()=>exportCSV(currentReport.exportRows,'TeFinanza-report-'+today()+'.csv');$('#csvExport').onclick=()=>exportCSV(selected('movementFilters').map(({id,date,description,amount,account,type,category,merchant,security,documentNo,invoiceNo,linkedView,originAccount})=>({date,description,amount,account,type,category,merchant,security,documentNo:documentNo||'',invoiceNo:invoiceNo||'',linkedSourceId:linkedView?id:'',originAccount:originAccount||''})),'TeFinanza-operazioni.csv');$('#csvImport').onclick=()=>$('#csvFile').click();$('#csvFile').onchange=async e=>{await importCSV(e.target.files[0]);e.target.value=''};$('#backupBtn').onclick=async()=>{let b=$('#backupBtn');b.disabled=true;try{await exportBackup()}catch(e){toast('Copia non esportata: '+e.message)}finally{b.disabled=false}};$('#restoreBtn').onclick=()=>$('#restoreFile').click();$('#restoreFile').onchange=async e=>{await restoreBackup(e.target.files[0]);e.target.value=''};$('#editBudget').onclick=()=>{modal(`<form id="budgetForm"><h2>Budget mensile</h2><label>Limite EUR<input id="budgetValue" type="number" min="1" step=".01" value="${state.budget}" required></label><div class="dialog-actions"><button type="button" class="btn" data-close>Annulla</button><button class="btn primary">Salva</button></div></form>`);$('#budgetForm').onsubmit=async e=>{e.preventDefault();if(await change(s=>s.budget=Number($('#budgetValue').value)))$('#modal').close()}};$('#clearDemo').onclick=async()=>{let n=state.movements.filter(m=>m.demo).length;if(!n)return toast('Non ci sono operazioni demo da rimuovere.');if(confirm('Rimuovere '+n+' operazioni demo? I saldi iniziali dei conti restano quelli di esempio: modificali nella gestione conti. Le tue operazioni confermate restano conservate.'))await change(s=>s.movements=s.movements.filter(m=>!m.demo))};
initialize();

function resetDialog(id){if(!ready)return toast('Attendi l’apertura dell’archivio.');if(!requiredAccounts())return;let selected=id?[state.accounts.find(a=>a.id===id)].filter(Boolean):state.accounts,names=selected.map(a=>a.name),count=state.movements.filter(m=>names.includes(m.account)).length,positions=state.positions.filter(p=>names.includes(p.account)).length;modal(`<form id="resetForm"><h2>${id?'Azzera '+esc(names[0]):'Cancella tutti i dati di prova'}</h2><p><b>${names.length} conti resteranno aperti con saldo 0,00 €.</b></p><p>Elimina ${count} movimenti e ${positions} posizioni, compresi gli importi iniziali.${id?'':' Elimina dall’archivio anche tutti i documenti, scontrini, articoli e categorie apprese.'}</p><p>${id?'I documenti originali e gli altri conti restano disponibili. Il movimento sul conto opposto di un giroconto resta conservato.':'Mantiene nomi, banche e tipi dei conti. I dati demo non ricompaiono alla riapertura. Puoi ripetere questa pulizia dopo ogni prova.'}</p><p class="small">L’ultimo azzeramento è annullabile da “Copia e ripristino” → “Annulla ultimo azzeramento”.</p><label class="check"><input type="checkbox" id="resetConsent" required> Confermo: cancella i dati e mantieni i conti a zero.</label><div class="dialog-actions"><button type="button" class="btn" data-close>Annulla</button><button class="btn primary" id="confirmReset">Cancella e azzera</button></div></form>`);$('#resetForm').onsubmit=async e=>{e.preventDefault();if(!$('#resetConsent').checked)return;$('#confirmReset').disabled=true;let before=structuredClone(state);delete before.resetBackup;let next=id?C.resetAccounts(state,names):C.clearTrialData(state);next.resetBackup={at:new Date().toISOString(),state:before};try{await commit(next);$('#modal').close();for(const key of ['movementFilters','archiveFilters','portfolioFilters','reportFilters'])setFilters(key,{});$('#productSearch').value='';showPage('accounts');toast('Pulizia completata: conti mantenuti e saldi azzerati.')}catch(e){$('#confirmReset').disabled=false;toast('Azzeramento non eseguito: '+e.message)}}}
$('#resetAllAccounts').onclick=()=>resetDialog();
$('#undoRestore').onclick=undoLastRestore;
$('#undoReset').onclick=async()=>{if(!state.resetBackup)return toast('Nessun azzeramento da annullare.');if(!confirm('Ripristinare la copia precedente all’ultimo azzeramento? Anche le modifiche successive saranno sostituite.'))return;try{await commit(structuredClone(state.resetBackup.state));toast('Dati precedenti ripristinati.')}catch(e){toast('Ripristino non riuscito: '+e.message)}};

$('#clearTrialData').onclick=()=>resetDialog();
$('#loadDemo').onclick=async()=>{if(!ready)return;if(state.movements.length||state.documents.length||state.positions.length)return toast('Per caricare la demo, azzera prima i dati di prova.');if(!confirm('Caricare operazioni di esempio nei conti disponibili? Potrai cancellarle con “Cancella dati di prova”.'))return;let names=new Set(state.accounts.map(a=>a.name)),rows=seed().filter(m=>names.has(m.account));if(!rows.length)return toast('Nessun conto compatibile con la demo. I tuoi conti sono conservati.');if(await change(s=>{s.movements=rows;s.demoMode=true})){showPage('home');toast('Demo caricata. Puoi azzerarla in qualsiasi momento.')}};

$('#importCopyText').onclick=()=>{if(!ready)return;modal(`<form id="copyTextForm"><h2>Importa una copia come testo</h2><p>Se il selettore file non risponde, incolla qui il contenuto di una copia TeFinanza. I dati vengono uniti all’archivio corrente; le operazioni già presenti vengono riconosciute per identificativo e per conto, data, importo e causale, rispettando il numero delle righe ripetute.</p><label>Contenuto della copia<textarea id="copyText" required spellcheck="false" autocomplete="off" placeholder="Incolla il contenuto della copia TeFinanza"></textarea></label><p id="copyImportStatus" class="small" role="status"></p><div class="dialog-actions"><button type="button" class="btn" data-close>Annulla</button><button class="btn primary" id="submitCopyText">Verifica e importa</button></div></form>`,true);$('#copyTextForm').onsubmit=async e=>{e.preventDefault();let button=$('#submitCopyText');button.disabled=true;try{let text=$('#copyText').value;if(text.length>25000000)throw Error('Copia troppo grande per questa modalità');let raw=JSON.parse(text.replace(/^\ufeff/,'')),incoming=C.migrate(raw);C.validate(incoming);let next=C.mergeCopy(state,incoming),files=[];for(const f of raw.originalFiles||[]){if(!next.documents.some(d=>d.id===f.id)||typeof f.data!=='string'||!/^data:(application\/pdf|image\/(jpeg|png|webp)|text\/plain);base64,/.test(f.data))throw Error('Originale non valido');files.push({id:f.id,name:String(f.name),blob:await(await fetch(f.data)).blob()})}let countBefore=state.movements.length;await commit(next,files);let added=state.movements.length-countBefore;$('#modal').close();showPage('accounts');toast('Importazione completata: '+added+' nuove operazioni, '+files.length+' originali archiviati.')}catch(error){$('#copyImportStatus').textContent='Importazione non eseguita: '+error.message;button.disabled=false}}};
